-- Music Appreciation course record. Safe to run more than once.
alter table public.courses add column if not exists video_url text;

insert into public.courses (slug, title, subject, credits, focus)
values ('music-appreciation-worship-arts', 'Music Appreciation and Worship Arts', 'Fine and Performing Arts', 1.0, $j$Music Appreciation and Worship Arts is a one credit fine and performing arts course that teaches students to listen to, understand, perform and use music for the glory of God. Students study the elements of music, music in Scripture and worship, the history of Western music and the great hymn writers, American traditions including spirituals, gospel, blues and jazz, the skills of singing, reading notation, ensemble playing, practice and performance, and the responsibilities of worship leading, wise listening, copyright and honesty, and service. Students keep a listening journal and a practice journal, perform a short piece for a parent, guardian or teacher, and apply what Scripture teaches about singing with the spirit and with understanding. Students should protect their hearing and voice and get adult permission and supervision before serving outside the home or church. The course aligns to the Florida music standards and ends with a final listening and performance portfolio and a final exam. Excellence, Faith, Purpose.$j$)
on conflict (slug) do nothing;
